import React, { useState } from 'react';
import ReactDOM from 'react-dom';
import {
  DataTable,
  TableContainer,
  Table,
  TableHead,
  TableRow,
  TableHeader,
  TableBody,
  TableCell,
  TableToolbar,
  TableBatchActions,
  TableBatchAction,
  TableSelectAll,
  TableSelectRow,
} from 'carbon-components-react';
import {
  Download16,
  Copy16,
  Edit16,
  Favorite16,
  Send16,
  TrashCan16,
} from '@carbon/icons-react';

const headers = [
  { key: 'name', header: 'Name' },
  { key: 'size', header: 'Size' },
];

// generate 6-8 rows with unique ids
const rows = Array.from({ length: 8 }, (_, i) => ({
  id: `row-${i}`,
  name: `File ${i + 1}`,
  size: `${Math.round(Math.random() * 100)} MB`, 
}));

function App() {
  return (
    // force small width to simulate mobile/small screen
    <div style={{ width: 320, margin: '1rem auto', border: '1px solid #ddd' }}>
      <DataTable rows={rows} headers={headers} isSortable>
        {({ rows, headers, getHeaderProps, getRowProps, getSelectionProps, selectedRows, selectAll, selectRow }) => (
          <TableContainer title="My Files">
            <TableToolbar>
              {/* batch actions will appear when selectedRows.length > 0 */}
              <TableBatchActions onCancel={selectAll} shouldShowBatchActions={selectedRows.length > 0}>
                <TableBatchAction renderIcon={Download16}>Download to</TableBatchAction>
                <TableBatchAction renderIcon={Edit16}>Move</TableBatchAction>
                <TableBatchAction renderIcon={Copy16}>Copy</TableBatchAction>
                <TableBatchAction renderIcon={Favorite16}>Favorite</TableBatchAction>
                <TableBatchAction renderIcon={Send16}>Send via packages</TableBatchAction>
                <TableBatchAction renderIcon={TrashCan16}>Delete</TableBatchAction>
              </TableBatchActions>
            </TableToolbar>
            <Table>
              <TableHead>
                <TableRow>
                  <TableSelectAll {...getSelectionProps()} />
                  {headers.map((header) => (
                    <TableHeader key={header.key} {...getHeaderProps({ header })}>
                      {header.header}
                    </TableHeader>
                  ))}
                </TableRow>
              </TableHead>
              <TableBody>
                {rows.map((row) => (
                  <TableRow key={row.id} {...getRowProps({ row })}>
                    <TableSelectRow {...getSelectionProps({ row })} />
                    {row.cells.map((cell) => (
                      <TableCell key={cell.id}>{cell.value}</TableCell>
                    ))}
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        )}
      </DataTable>
    </div>
  );
}

// render into the page
ReactDOM.render(<App />, document.getElementById('root'));
